def compare_versions(a: str, b: str) -> int:
    def split_parts(v: str):
        # ignore build metadata
        v = v.split('+', 1)[0]
        if '-' in v:
            core, pre = v.split('-', 1)
            pre_ids = pre.split('.')
        else:
            core = v
            pre_ids = []
        major, minor, patch = map(int, core.split('.'))
        return (major, minor, patch, pre_ids)

    def compare_identifiers(id1: str, id2: str) -> int:
        is_num1 = id1.isdigit()
        is_num2 = id2.isdigit()
        if is_num1 and is_num2:
            n1, n2 = int(id1), int(id2)
            return (n1 > n2) - (n1 < n2)
        if is_num1 and not is_num2:
            return -1
        if not is_num1 and is_num2:
            return 1
        return (id1 > id2) - (id1 < id2)

    m1, mi1, p1, pre1 = split_parts(a)
    m2, mi2, p2, pre2 = split_parts(b)

    # compare core
    for x, y in ((m1, m2), (mi1, mi2), (p1, p2)):
        if x != y:
            return (x > y) - (x < y)

    # core equal, handle pre-release
    if not pre1 and not pre2:
        return 0
    if not pre1:
        return 1  # a has no pre-release, so higher
    if not pre2:
        return -1

    # compare each identifier
    for id1, id2 in zip(pre1, pre2):
        cmp = compare_identifiers(id1, id2)
        if cmp:
            return cmp

    # all compared equal, shorter list is lower
    return (len(pre1) > len(pre2)) - (len(pre1) < len(pre2))
